var Pm10ComMenu = {};

/**
 * 함수명   : Pm10ComMenu.gfn_getHomeUrl
 * 함수설명 : 인터넷등기소 메인화면
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2022.08.04
 * 작성자   : 장기순
 */
Pm10ComMenu.gfn_getHomeUrl = function() {
	return Pm10ComGlobal.HOME_PAGE_URL;
};

/**
 * 함수명   : Pm10ComMenu.gfn_getContsUrl
 * 함수설명 : 인터넷등기소 컨텐츠화면
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2022.08.04
 * 작성자   : 장기순
 */
Pm10ComMenu.gfn_getContsUrl = function() {
	return Pm10ComGlobal.CONTS_PAGE_URL;
};

/**
 * 함수명   : Pm10ComMenu.gfn_getloginUrl
 * 함수설명 : 인터넷등기소 로그인화면
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2022.08.04
 * 작성자   : 장기순
 */
Pm10ComMenu.gfn_getloginUrl = function() {
	return Pm10ComGlobal.LOGIN_PAGE_URL;
};

/**
 * 함수명   : Pm10ComMenu.gfn_getMoveToLoginYn
 * 함수설명 : 로그인 경유 여부조회
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2022.08.04
 * 작성자   : 장기순
 */
Pm10ComMenu.gfn_getMoveToLoginYn = function() {
	return Pm10ComGlobal.MOVE_TO_LOGIN_YN;
};

/**
 * 함수명   : Pm10ComMenu.gfn_setMoveToLoginYn
 * 함수설명 : 로그인 경유 여부 설정
 * 파라메터 : 로그인경유여부(Y:로그인페이지를 경유하여 메뉴이동 할 경우, N:바로메뉴이동 할 경우)
 * 리턴     : N/A
 * 작성일   : 2022.08.04
 * 작성자   : 장기순
 */
Pm10ComMenu.gfn_setMoveToLoginYn = function(yn) {
	Pm10ComGlobal.MOVE_TO_LOGIN_YN = yn;
};

/**
 * 함수명   : Pm10ComMenu.gfn_getReturnMenuId
 * 함수설명 : 로그인화면에서 리턴 할 메뉴
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2022.08.04
 * 작성자   : 장기순
 */
Pm10ComMenu.gfn_getReturnMenuId = function() {
	return Pm10ComGlobal.RETURN_MENU_ID;
};

/**
 * 함수명   : Pm10ComMenu.gfn_setReturnMenuId
 * 함수설명 : 로그인화면에서 리턴 할 메뉴 설정
 * 파라메터 : 메뉴아이디
 * 리턴     : N/A
 * 작성일   : 2022.08.04
 * 작성자   : 장기순
 */
Pm10ComMenu.gfn_setReturnMenuId = function(menuId) {
	Pm10ComGlobal.RETURN_MENU_ID = menuId;
};

/**
 * 함수명   : Pm10ComMenu.gfn_getIrosDevMode
 * 함수설명 : 서버환경
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2022.08.04
 * 작성자   : 장기순
 */
Pm10ComMenu.gfn_getIrosEnvType = function() {
	return Pm10ComGlobal.IROS_ENV_TYPE;
};

/**
 * 함수명   : Pm10ComMenu.gfn_setIrosEnvType
 * 함수설명 : 인터넷등기소 현재 서버환경 조회
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2022.08.04
 * 작성자   : 장기순
 */
Pm10ComMenu.gfn_setIrosEnvType = function() {
	//서버구분(로컬:L, 개발:D, 검증:V, 운영:R)	
	Pm10ComGlobal.IROS_ENV_TYPE = Pm10ComRigt.gfn_isEnvType();   
};

/**
 * 함수명   : Pm10ComMenu.gfn_getIrosDevMode
 * 함수설명 : 개발자모드여부
 * 파라메터 : N/A	
 * 리턴     : N/A
 * 작성일   : 2022.08.04
 * 작성자   : 장기순
 */
Pm10ComMenu.gfn_getIrosDevMode = function() {
	return Pm10ComGlobal.IROS_DEV_MODE;
};

/**
 * 함수명   : Pm10ComMenu.gfn_setIrosDevMode
 * 함수설명 : 로컬 및 개발서버 개발자모드 설정 조회 
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2022.08.04
 * 작성자   : 장기순
 */
Pm10ComMenu.gfn_setIrosDevMode = function() {
	//개발자모드여부(Y:true:로그인체크안함, N:false:로그인체크함)
	Pm10ComGlobal.IROS_DEV_MODE = Pm10ComRigt.gfn_isDevMode();
};

/**
 * 함수명   : Pm10ComMenu.gfn_openMenu
 * 함수설명 : 인터넷등기소 header Main, header Side, location, sideBar 화면에서 각 시스템 별 id 메뉴이동
 * 파라메터 : 메뉴아이디, 입력파라미터
 * 리턴     : N/A
 * 작성일   : 2022.08.04
 * 작성자   : 장기순
 */
Pm10ComMenu.gfn_openMenu = function(menuId, paramData, nmbrLoginCls) {
    
	/*
	    @@ 메뉴이동 케이스 정리 ===============================================  
	     - case 01 : header 에서 유효한 id를 가져와 처리할 경우, paramData 정보 없음 (pm10.등기외부포털)
	     - case 02 : location 에서 유효한 id를 가져와 처리할 경우, paramData 정보 없음 (pm10.등기외부포털)
	     - case 03 : side bar 에서 유효한 id를 가져와 처리할 경우, paramData 정보 없음 (pm10.등기외부포털)
	     - case 04 : footer 에서 유효한 id를 가져와 처리할 경우, paramData 정보 없음 (pm10.등기외부포털)
	     - case 05 : 각 화면에서 유효한 id를 가져와 화면이동, paramData 정보가 있을 수 있음(인터넷등기소전체)
	*/  
	/*
	console.log("@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@");
	console.log("@ gfn_openMenu 파라미터값 log start!!");
	console.log("@ 메뉴아이디 {} => ",menuId);
	console.log("@ 파라미터값 {} => ",paramData);
	
	console.log(">>>>>>>>>>>>>>>>>>>>");
	console.log("@메뉴권한정보 세팅 전 {} => ",Pm10ComRigt.gfn_getRigtMenuId());
	*/
	
    //메시지 : {이동할 메뉴가} 존재하지 않는 {화면} 입니다.             
    if (com.util.isEmpty(menuId)) { 
       com.message.openMessage(Pm10ComUtil.gfn_getMesOption('info', 'pm10.message.info.web.p0.0019', '이동할 메뉴가^화면'));
       return false;   
    }    
    
    //이동구분
    var moveCls = "menu";    
    if (com.util.isNotEmpty(nmbrLoginCls)) { 
    	moveCls = "nmbr_menu"; //비회원처리가 필요한화면일 경우
    }
    
   	//id 정보를 전달    
  	com.page.getTopPage().scwin.goToMenuPage(moveCls, menuId, paramData);
};

/**
 * 함수명   : Pm10ComMenu.gfn_movePage
 * 함수설명 : 인터넷등기소 시스템 별 url 화면이동
 * 파라메터 : 메뉴경로, 입력파라미터
 * 리턴     : N/A
 * 작성일   : 2022.08.04
 * 작성자   : 장기순
 */
Pm10ComMenu.gfn_movePage = function(moveUrl, paramData, nmbrLoginCls) {
	
	/*
	    각시스템에서 유효한 url를 가져와 화면이동, paramData 정보가 있을 수 있음(인터넷등기소전체)
	*/  
	/*
	console.log("@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@");
	console.log("@ gfn_movePage 파라미터값 log start!!");
	console.log("@ 메뉴경로 {} => ",moveUrl);
	console.log("@ 파라미터값 {} => ",paramData);
	
	console.log(">>>>>>>>>>>>>>>>>>>>");
	console.log("@메뉴권한 상위로케이션 정보 세팅 {} => ",Pm10ComRigt.gfn_getRigtMenuId());
	console.log(">>>>>>>>>>>>>>>>>>>>");
	*/
	
    //메시지 : {이동할 화면이} 존재하지 않는 {화면} 입니다.             
    if (com.util.isEmpty(moveUrl)) { 
       com.message.openMessage(Pm10ComUtil.gfn_getMesOption('info', 'pm10.message.info.web.p0.0019', '이동할 화면이^화면'));
       return false;   
    }    
    
    //이동구분
	var moveCls = "page";
	if (com.util.isNotEmpty(nmbrLoginCls)) { 
    	moveCls = "nmbr_page"; //비회원처리가 필요한화면일 경우
    }
	
	//url 정보를 전달
	com.page.getTopPage().scwin.goToMovePage(moveCls, moveUrl, paramData);
	window.scrollTo(0, 0);
};
